import itertools, json

# Variables: Fam, All, GA, Frozen, Erotic, Can (children can watch without guidance)
models = []
for Fam, All, GA, Frozen, Erotic, Can in itertools.product([False, True], repeat=6):
    imp = lambda a, b: (not a) or b
    ok = (
        imp(All, Can)
        and imp(Erotic, not Can)
        and imp(GA, All)
        and imp(Fam, GA)
        and imp(Frozen, Fam)
        and (Fam or All)  # inclusive reading
    )
    if ok:
        models.append((Fam, All, GA, Frozen, Erotic, Can))

# Conclusion: (Erotic and Frozen) or (not Erotic and not Frozen)
def concl(m):
    Frozen, Erotic = m[3], m[4]
    return (Erotic and Frozen) or ((not Erotic) and (not Frozen))

vals = {concl(m) for m in models}
if vals == {True}:
